def prop(kind,x=960,y=470,scale=1,**kw):return dict(id=kw.pop('id',kind),kind=kind,x=x,y=y,scale=scale,**kw)
def board(text,sub='',x=960,y=470,scale=1,**kw):return prop('board',x,y,scale,text=text,subtext=sub,**kw)
def actor(role,x=960,y=805,scale=.78,**kw):return dict(id=kw.pop('id',role),role=role,x=x,y=y,scale=scale,**kw)
def link(x1,y1,x2,y2,label='',crossed=False):return dict(from_=[x1,y1],to=[x2,y2],label=label,crossed=crossed)
def S(n,s,scene,setname,subject,shows,props=None,actors=None,size='wide',focus=None,date='',heading='',note='',location='',links=None,words=None,angle=0,illustrative=None):
 text=re.split(r'(?<=[.!?])\s+',SRC[n-1]['text'])[s-1] if words is None else words
