def authored_plan():
 expected=''.join(n['text'].replace(' ','') for n in SRC)
 actual=''.join(n['text'].replace(' ','') for n in PLAN)
 assert actual==expected, 'Storyboard must preserve the exact narration order and words'
 return copy.deepcopy(PLAN)
